import copy

def merge_config(base, patch):
    """
    Merge nested configuration dictionaries recursively.
    A patch value of None is stored as None. All other patch values replace the base value.
    Return an independent result, including lists or dictionaries kept from either side.
    """
    if base is None:
        return patch
    if patch is None:
        return base

    if isinstance(base, dict) and isinstance patch, dict):
        merged = copy.copy(base)
        for key, value in patch.items():
            if key in merged:
                merged[key] = merge_config(merged[key], value)
            else:
                merged[key] = value
        return merged
    elif isinstance(base, list) and isinstance patch, list):
        merged = copy.copy(base)
        for i, value in enumerate(base):
            if i < len(merged) and isinstance(merged[i], dict):
                merged[i] = merge_config(merged[i], patch[i])
            else:
                merged.append(value)
        return merged
    else:
        return patch

def page_bounds(page, size, total):
    if page <= 0 or size <= 0 or total < 0:
        raise ValueError("page, size, and total must be positive")
    start = max(0, page * size)
    stop = min(start + size, total)
    return start, stop

import collections

def summarize_jobs(jobs):
    summary = collections.defaultdict(lambda: (0, 0))
    for job in jobs:
        summary[job.status] = (summary[job.status][0] + 1, summary[job.status][1] + job.size)
    return {status: (count, total_size) for status, (count, total_size) in summary.items() if total_size != 0}

