import os

def write_all(w, data):
    if not data:
        raise ValueError("Data cannot be empty")

    total_bytes = 0
    while data:
        bytes_copied = w(data)
        if bytes_copied == 0:
            raise os.error("Write returned zero bytes")
        if bytes_copied < len(data):
            raise os.error("Write returned fewer bytes than offered")
        total_bytes += bytes_copied
        data = data[bytes_copied:]

    return total_bytes

