import time

def ttl_lookup(cache, key, now, fetch, ttl):
    if key not in cache:
        return None

    expires_at, value = cache[key]

    if expires_at > now:
        return value

    try:
        result = fetch(key)
        cache[key] = (now + ttl, result)
        return result
    except Exception as e:
        cache[key] = (now + ttl, None)
        raise e

import os

def select_manifest(root):
    manifest_paths = []
    for root, dirs, files in os.scandir(root):
        if root.is_dir() and root.name.endswith('.manifest'):
            continue
        for file in files:
            if file.endswith('.manifest'):
                manifest_paths.append(os.path.join(root, file))
    return sorted(set([os.path.relpath(path, root) for path in manifest_paths]))

