import collections

def first_unique(values, count):
    if count <= 0:
        return []

    seen = collections.defaultdict(int)
    for value in values:
        seen(value) += 1

    unique_values = []
    for value in values:
        if seen(value) == 1:
            unique_values.append(value)
            if len unique_values) == count:
                return unique_values

    return unique_values

