import contextlib

@contextlib.contextmanager
def capture_append(target):
    try:
        yield target
    except Exception as e:
        target.clear()
        raise e

def main():
    with capture_append([1, 2, 3]) as lst:
        lst.append(4)
        lst.append(5)
        print("Inside with block:", lst)
    print("Outside with block:", lst)

if __name__ == "__main__":
