import itertools

def pad_rows(rows, width, fill=None):
    if width < 0:
        raise ValueError("width must be nonnegative")

    for row in rows:
        if isinstance(row, str):
            row = list(row)
        elif not isinstance(row, (list, tuple)):
            row = [row]

        if len(row) < width:
            row.extend([fill] * (width - len(row)))
        elif len(row) > width:
            row = row[:width]

        yield row
